using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;

namespace MyApp.Evals;

[TestClass]
public sealed class EvalTests
{
    private static ReportingConfiguration? s_reportingConfiguration;

    [AssemblyInitialize]
    public static void AssemblyInitialize(TestContext context)
    {
        s_reportingConfiguration = CreateReportingConfiguration();
    }

    [AssemblyCleanup]
    public static async Task AssemblyCleanup()
    {
        if (s_reportingConfiguration is not null)
        {
            await s_reportingConfiguration.GenerateReportAsync();
        }
    }

    private static ReportingConfiguration CreateReportingConfiguration()
    {
        var evaluators = new IEvaluator[]
        {
            new CoherenceEvaluator(),
            new RelevanceEvaluator(),
            new FluencyEvaluator(),
            new GroundednessEvaluator(),
        };

        var chatConfiguration = new ChatConfiguration(GetChatClient());

        return new ReportingConfiguration(
            storageRootPath: Path.Combine(
                Directory.GetCurrentDirectory(), "eval-results"),
            evaluators: evaluators,
            chatConfiguration: chatConfiguration);
    }

    private static IChatClient GetChatClient()
    {
        // Use the same model for evaluation as the one being tested.
        // In CI, set AZURE_OPENAI_ENDPOINT and AZURE_OPENAI_CHAT_DEPLOYMENT env vars.
        var endpoint = Environment.GetEnvironmentVariable("AZURE_OPENAI_ENDPOINT")
            ?? throw new InvalidOperationException(
                "Set the AZURE_OPENAI_ENDPOINT environment variable.");

        var deployment = Environment.GetEnvironmentVariable("AZURE_OPENAI_CHAT_DEPLOYMENT")
            ?? "gpt-4o-mini";

        return new Azure.AI.OpenAI.AzureOpenAIClient(
            new Uri(endpoint),
            new Azure.Identity.DefaultAzureCredential())
            .GetChatClient(deployment)
            .AsIChatClient();
    }

    [TestMethod]
    public async Task Chat_responds_coherently_to_greeting()
    {
        await using var scenarioRun =
            await s_reportingConfiguration!.CreateScenarioRunAsync(TestContext.Current);

        var chatClient = GetChatClient();

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Hello, how are you?")
        };

        var response = await chatClient.GetResponseAsync(messages);

        messages.Add(response.Message);

        await scenarioRun.EvaluateAsync(messages);

        scenarioRun.AssertNoNumericMetricsBelowThreshold(3);
    }

    [TestMethod]
    public async Task Chat_answers_factual_question()
    {
        await using var scenarioRun =
            await s_reportingConfiguration!.CreateScenarioRunAsync(TestContext.Current);

        var chatClient = GetChatClient();

        var messages = new List<ChatMessage>
        {
            new(ChatRole.System, "You are a helpful assistant. Answer concisely."),
            new(ChatRole.User, "What is the capital of France?")
        };

        var response = await chatClient.GetResponseAsync(messages);

        messages.Add(response.Message);

        await scenarioRun.EvaluateAsync(messages);

        scenarioRun.AssertNoNumericMetricsBelowThreshold(3);
    }
}

